"""Script-free portfolio action queue. Never renders HTML from the snapshots."""
from html import escape


def e(value): return escape(str(value), quote=True)


def render(result):
    sites=result['sites']; counts={p:sum(s['plan']['priority_counts'][p] for s in sites) for p in ('P0','P1','P2')}
    cards=[]
    for site in sorted(sites,key=lambda s:(-s['plan']['priority_counts']['P0'],-s['plan']['priority_counts']['P1'],s['label'])):
        report=site['report']; queue=site['plan']; topics=report['topics']
        actions=''.join('<tr><td><strong>'+e(a['priority'])+'</strong></td><td>'+e(a['code'])+'</td><td>'+e(a['url'])+('<small>'+e(a['subject'])+'</small>' if a['subject'] else '')+'</td><td>'+e(a['action'])+'</td></tr>' for a in queue['actions'][:100])
        topic_rows=''.join('<tr><td>'+e(t['id'])+'</td><td>'+e(t['language'])+'</td><td>'+e(t['status'])+'</td><td>'+e(t['target'])+'</td></tr>' for t in topics)
        page_rows=''.join('<tr><td>'+e(url)+'</td><td>'+e(p['inbound_observed'])+'</td><td>'+e(p['depth'] if p['depth'] is not None else '—')+'</td><td>'+e(p['reachability'])+'</td><td>'+e(', '.join(k+': '+v['status'] for k,v in p['structured_data']['profiles'].items()) or 'Not configured')+'</td></tr>' for url,p in sorted(report['pages'].items()))
        cards.append(f'''<section><div class="heading"><div><h2>{e(site['label'])}</h2><p>{e(report['origin'])}</p></div><strong class="priority">{e(queue['priority_counts']['P0'])} P0</strong></div>
<div class="stats"><div><span>Verified eligible pages</span><b>{e(report['eligible_verified'])}/{e(report['eligible_expected'])}</b></div><div><span>Topics covered on target</span><b>{sum(t['status']=='COVERED' for t in topics)}/{len(topics)}</b></div><div><span>P1 reviews</span><b>{e(queue['priority_counts']['P1'])}</b></div><div><span>P2 reviews</span><b>{e(queue['priority_counts']['P2'])}</b></div></div>
<details open><summary>Prioritized action queue ({len(queue['actions'])}; showing up to 100)</summary><div class="table"><table><thead><tr><th>Priority</th><th>Evidence</th><th>Target</th><th>Review action</th></tr></thead><tbody>{actions or '<tr><td colspan="4">No actions in declared scope.</td></tr>'}</tbody></table></div></details>
<details><summary>Declared topic coverage</summary><div class="table"><table><thead><tr><th>Topic</th><th>Language</th><th>Status</th><th>Target</th></tr></thead><tbody>{topic_rows or '<tr><td colspan="4">No topics configured.</td></tr>'}</tbody></table></div></details>
<details><summary>Navigation and local schema observations</summary><div class="table"><table><thead><tr><th>Page</th><th>Inbound</th><th>Depth</th><th>Reachability</th><th>Schema profile</th></tr></thead><tbody>{page_rows or '<tr><td colspan="5">No supported observations.</td></tr>'}</tbody></table></div></details>
<p class="digest">Evidence SHA-256: {e(queue['evidence_sha256'])}</p></section>''')
    metrics=''.join(f'<div><span>{e(label)}</span><b>{e(value)}</b></div>' for label,value in [('Websites',len(sites)),('P0 technical defects',counts['P0']),('P1 priority reviews',counts['P1']),('P2 other reviews',counts['P2'])])
    return '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><title>Web Growth Guard | Growth Intelligence</title><style>
:root{font-family:system-ui,sans-serif;color:#17363c;background:#edf4f4;--muted:#526b72;--line:#d6e4e4}*{box-sizing:border-box}body{margin:0;padding:24px}main{max-width:1120px;margin:auto}header{margin-bottom:22px}.eyebrow{letter-spacing:.14em;color:#0f766e;font-size:12px;font-weight:800}h1{font-size:clamp(28px,5vw,42px);margin:8px 0}h2{font-size:20px;margin:0}p{color:var(--muted);line-height:1.5;margin:4px 0 10px}.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:10px;margin:14px 0}.stats div{background:#fff;padding:14px;border:1px solid var(--line);border-radius:10px;display:grid;gap:5px}.stats span{font-size:12px;color:var(--muted)}b{font-size:26px}section{background:white;border:1px solid var(--line);padding:20px;border-radius:14px;margin:18px 0}.heading{display:flex;align-items:start;justify-content:space-between;gap:10px;overflow-wrap:anywhere}.priority{font-size:15px;color:#a13a32;border:1px solid currentColor;padding:5px 10px;border-radius:8px;white-space:nowrap}section .stats div{background:#f4f8f8}details{border-top:1px solid var(--line);padding:12px 0}summary{cursor:pointer;font-weight:650}.table{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px;margin-top:10px}td,th{text-align:left;vertical-align:top;padding:10px;border-bottom:1px solid var(--line);overflow-wrap:anywhere}th{color:var(--muted);font-size:11px;text-transform:uppercase}small{display:block;color:var(--muted);margin-top:4px}.digest{font-size:11px;overflow-wrap:anywhere}footer{font-size:13px;color:var(--muted)}@media(prefers-color-scheme:dark){:root{color:#e5eeee;background:#152c31;--muted:#b2c8cc;--line:#39555b}section,.stats div{background:#203a40}section .stats div{background:#29464d}.eyebrow{color:#8bdacf}.priority{color:#ffb7b0}}</style></head><body><main><header><div class="eyebrow">WEB GROWTH GUARD / INTELLIGENCE</div><h1>Growth action queue</h1><p>Fresh, bounded HTML snapshots. Priorities are policy-based, not traffic or revenue forecasts.</p></header><div class="stats">'''+metrics+'</div>'+''.join(cards)+'''<footer>Review all actions independently. Topic coverage is lexical, reachability is limited to declared pages, and structured data checks are a subset. No live website access, script execution, or deployment authorization. Keep real reports private.</footer></main></body></html>'''
